export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-sve-0001", "section": "service", "who": "reader", "text": "НА УТРЕНИ"},
  {"id": "cu-sve-0002", "section": "service", "who": "reader", "text": "О часе утреннем параекклисиарх взем благословение у настоятеля, исходит и ударяет в великое, и клеплет довольно. И вшед во храм, вжигает свещи вся, и кандила: устрояет же сосуды два со углием горящим, и влагает в них фимиама много благовоннаго, и поставляет един сосуд среди церкве, другий же во святом алтаре, яко да исполнится церковь вся благовония. Таже настоятель вшед во святый алтарь со иереи и диаконы, облачатся в весь светлейший сан. И раздает свещи братии, и вземлет Честный Крест: кадило же вземлет диакон. Иерей же святое Евангелие, ин иерей образ Воскресения Христова: и ставятся лицем на запад. И затворят врата церковная, яже к западу. Исходит настоятель со иереи в притвор, северными дверьми, предыдущим пред ним диаконом со двема свещами, и оба лика поюще стихиру, глас 6:"},
  {"id": "cu-sve-0003", "section": "service", "who": "choir", "text": "Воскресе́ние Твое́, Христе́ Спа́се, / А́нгели пою́т на небесе́х, / и нас на земли́ сподо́би / чи́стым се́рдцем / Тебе́ сла́вити."},
  {"id": "cu-sve-0004", "section": "service", "who": "choir", "text": "Таже ударяют во вся кампаны и тяжкая, и клеплют довольно. И вшедше в притвор, станут со Евангелием, и со образом, лицем на запад, якоже указася прежде. Таже настоятель вземлет у диакона кадило в правую руку, Крест же в левую, и кадит образы, и клиросы, и братию по обычаю. Диакону же предносящу пред ним свещу горящу. Братия же вси стоят держаще свещи своя, со вниманием молящеся в себе, и благодаряще нас ради пострадавшаго и воскресшаго Христа Бога нашего. По скончании же каждения, приходит настоятель пред великия врата церкве, и покадит диакона, предстояшаго ему со свещею. Тогда взем кадило диакон от руку настоятеля, и покадит самого настоятеля. И паки восприим настоятель кадило, став пред церковными дверьми, зря на восток, и назнаменает великия врата церкве, [затвореная суща], кадилом крестообразно, трижды, держа в левой руце Честный Крест, и светильником стоящим со обою страну. И велегласно возгласит:"},
  {"id": "cu-sve-0005", "section": "service", "who": "deacon", "text": "Сла́ва Святе́й, и Единосу́щней, и Животворя́щей, и Нераздели́мей Тро́ице, всегда́, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0006", "section": "service", "who": "rubric", "text": "И нам отвещающим:"},
  {"id": "cu-sve-0007", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-sve-0008", "section": "service", "who": "deacon", "text": "Начинает настоятель, с прочими служители, велегласно настоящий"},
  {"id": "cu-sve-0009", "section": "service", "who": "choir", "text": "Тропарь, во глас 5:"},
  {"id": "cu-sve-0010", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0011", "section": "service", "who": "choir", "text": "И мы тойжде поем подобне, со сладкопением. Поется же сей тропарь трижды от настоятеля, и трижды от нас."},
  {"id": "cu-sve-0012", "section": "service", "who": "choir", "text": "Таже настоятель глаголет стихи: Первый стих:"},
  {"id": "cu-sve-0013", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-sve-0014", "section": "service", "who": "rubric", "text": "И на кийждо стих мы поем тропарь весь по единожды:"},
  {"id": "cu-sve-0015", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: Вторый стих:"},
  {"id": "cu-sve-0016", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sve-0017", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды. Третий стих:"},
  {"id": "cu-sve-0018", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-sve-0019", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sve-0020", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-sve-0021", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-sve-0022", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sve-0023", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-sve-0024", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sve-0025", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-sve-0026", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых: единожды."},
  {"id": "cu-sve-0027", "section": "service", "who": "rubric", "text": "Таже настоятель поет вышшим гласом:"},
  {"id": "cu-sve-0028", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в."},
  {"id": "cu-sve-0029", "section": "service", "who": "rubric", "text": "И отверзает врата."},
  {"id": "cu-sve-0030", "section": "service", "who": "rubric", "text": "Входит настоятель с Честным Крестом, предыдущим ему со двема лампадами, и братиям поющим:"},
  {"id": "cu-sve-0031", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0032", "section": "service", "who": "rubric", "text": "Таже ударяют во вся кампаны и клеплют довольно, три звоны."},
  {"id": "cu-sve-0033", "section": "service", "who": "rubric", "text": "Вшед же настоятель со иереи во святый алтарь. И диакон глаголет ектению великую:"},
  {"id": "cu-sve-0034", "section": "service", "who": "deacon", "text": "Ми́ром Го́споду помо́лимся. Возглас:"},
  {"id": "cu-sve-0035", "section": "service", "who": "deacon", "text": "Я́ко подоба́ет Тебе́ вся́кая сла́ва:"},
  {"id": "cu-sve-0036", "section": "service", "who": "choir", "text": "КАНОН, ГЛАС 1."},
  {"id": "cu-sve-0037", "section": "service", "who": "rubric", "text": "И начинает предстоятель канон, творение господина Иоанна Дамаскина. Глас 1. Ирмос:"},
  {"id": "cu-sve-0038", "section": "service", "who": "choir", "text": "Воскресе́ния день:"},
  {"id": "cu-sve-0039", "section": "service", "who": "rubric", "text": "Ирмосы на 4: и тропари на 12, с припевы:"},
  {"id": "cu-sve-0040", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0041", "section": "service", "who": "rubric", "text": "И паки последи кийждо лик ирмос. Последи же на сходе Катавасия, ирмос тойже:"},
  {"id": "cu-sve-0042", "section": "service", "who": "choir", "text": "Воскресе́ния день: И по нем"},
  {"id": "cu-sve-0043", "section": "service", "who": "choir", "text": "Xристос воскре́се:"},
  {"id": "cu-sve-0044", "section": "service", "who": "rubric", "text": "весь трижды. Творит же начало канона на куюждо песнь всегда предстоятель, десной или левой стране случившейся начати. И кадит в начале канона святыя иконы и оба лики, и братию по чину. И по коейждо песни бывает ектениа малая вне олтаря, якоже рехом, во святый сей день. Возглас внутрь олтаря от иереа. По 1-й песни поет десная страна. По 3-й же поет левая. Сице поем и по прочих песнех."},
  {"id": "cu-sve-0045", "section": "service", "who": "choir", "text": "Песнь 1. Ирмос:"},
  {"id": "cu-sve-0046", "section": "service", "who": "choir", "text": "Воскресе́ния день, / просвети́мся, лю́дие. / Па́сха, Госпо́дня Па́сха, / от сме́рти бо к жи́зни, / и от земли́ к небеси́, / Христо́с Бог нас преведе́, / побе́дную пою́щия. Припев:"},
  {"id": "cu-sve-0047", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0048", "section": "service", "who": "choir", "text": "Очи́стим чу́вствия, и у́зрим / непристу́пным све́том / Воскресе́ния, Христа́ блиста́ющася, / и ра́дуйтеся, реку́ща, / я́сно да услы́шим, / побе́дную пою́ще. Припев:"},
  {"id": "cu-sve-0049", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0050", "section": "service", "who": "choir", "text": "Небеса́ у́бо досто́йно да веселя́тся, / земля́ же да ра́дуется, / да пра́зднует же мир, / ви́димый же весь и неви́димый: / Христо́с бо воста́, / весе́лие ве́чное. Катавасия:"},
  {"id": "cu-sve-0051", "section": "service", "who": "choir", "text": "Воскресе́ния день: И тропарь:"},
  {"id": "cu-sve-0052", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0053", "section": "service", "who": "rubric", "text": "Таже ектениа, и возглас:"},
  {"id": "cu-sve-0054", "section": "service", "who": "choir", "text": "Я́ко Твоя́ держа́ва, и Твое́ есть Ца́рство, и си́ла, и сла́ва Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0055", "section": "service", "who": "choir", "text": "Песнь 3. Ирмос:"},
  {"id": "cu-sve-0056", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое, / не от ка́мене непло́дна чудоде́емое, / но нетле́ния исто́чник / из гро́ба одожди́вша Христа́, / в Не́мже утвержда́емся. Припев:"},
  {"id": "cu-sve-0057", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0058", "section": "service", "who": "choir", "text": "Ны́не вся испо́лнишася све́та, / не́бо же и земля́, и преиспо́дняя: / да пра́зднует у́бо вся тварь / воста́ние Христо́во, / в не́мже утвержда́ется. Припев:"},
  {"id": "cu-sve-0059", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0060", "section": "service", "who": "choir", "text": "Вчера́ спогребо́хся Тебе́, Христе́, / совостаю́ днесь / воскре́сшу Тебе́, / сраспина́хся Тебе́ вчера́, / Сам мя спросла́ви, Спа́се, во Ца́рствии Твое́м. Катавасия:"},
  {"id": "cu-sve-0061", "section": "service", "who": "choir", "text": "Прииди́те, пи́во пие́м но́вое: И тропарь:"},
  {"id": "cu-sve-0062", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0063", "section": "service", "who": "rubric", "text": "Таже ектениа, и возглас:"},
  {"id": "cu-sve-0064", "section": "service", "who": "choir", "text": "Я́ко Ты еси́ Бог наш, и Тебе́ сла́ву возсыла́ем, Отцу́ и Сы́ну и Свято́му Ду́ху, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0065", "section": "service", "who": "choir", "text": "Ипакои, глас 4:"},
  {"id": "cu-sve-0066", "section": "service", "who": "choir", "text": "Предвари́вшия у́тро я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго, / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-sve-0067", "section": "service", "who": "rubric", "text": "И чтение в Григории Богослове, егоже начало:"},
  {"id": "cu-sve-0068", "section": "service", "who": "reader", "text": "На стра́жи мое́й ста́ну:"},
  {"id": "cu-sve-0069", "section": "service", "who": "rubric", "text": "По чтении же паки вжигают свещи братия."},
  {"id": "cu-sve-0070", "section": "service", "who": "choir", "text": "Песнь 4. Ирмос:"},
  {"id": "cu-sve-0071", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи / богоглаго́ливый Авваку́м / да ста́нет с на́ми и пока́жет / светоно́сна А́нгела / я́сно глаго́люща: / днесь спасе́ние ми́ру, / я́ко воскре́се Христо́с, / я́ко всеси́лен. Припев:"},
  {"id": "cu-sve-0072", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0073", "section": "service", "who": "choir", "text": "Му́жеский у́бо пол, / я́ко разве́рзый де́вственную утро́бу, / яви́ся Христо́с, / я́ко челове́к же, / А́гнец нарече́ся: / непоро́чен же, / я́ко невку́сен скве́рны, / на́ша Па́сха, / и я́ко Бог и́стинен / соверше́н рече́ся. Припев:"},
  {"id": "cu-sve-0074", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0075", "section": "service", "who": "choir", "text": "Я́ко единоле́тный а́гнец, / благослове́нный нам вене́ц Христо́с, / во́лею за всех закла́н бысть, / Па́сха чисти́тельная, / и па́ки из гро́ба кра́сное / пра́вды нам возсия́ Со́лнце. Припев:"},
  {"id": "cu-sve-0076", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0077", "section": "service", "who": "choir", "text": "Богооте́ц у́бо Дави́д / пред се́нным ковче́гом скака́ше игра́я, / лю́дие же Бо́жии святи́и, / образо́в сбытие́ зря́ще, / весели́мся Боже́ственне, / я́ко воскре́се Христо́с, / я́ко Всеси́лен. Катавасия:"},
  {"id": "cu-sve-0078", "section": "service", "who": "choir", "text": "На Боже́ственней стра́жи: И тропарь:"},
  {"id": "cu-sve-0079", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0080", "section": "service", "who": "rubric", "text": "Ектениа, и возглас:"},
  {"id": "cu-sve-0081", "section": "service", "who": "choir", "text": "Я́ко Благ и Человеколю́бец Бог еси́, и Тебе́ сла́ву возсыла́ем, Отцу́ и Сы́ну и Свято́му Ду́ху, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0082", "section": "service", "who": "choir", "text": "Песнь 5. Ирмос:"},
  {"id": "cu-sve-0083", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́, / и вме́сто ми́ра песнь принесе́м Влады́це, / и Христа́ у́зрим / пра́вды Со́лнце, / всем жизнь возсия́юща. Припев:"},
  {"id": "cu-sve-0084", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0085", "section": "service", "who": "choir", "text": "Безме́рное Твое́ благоутро́бие, / а́довыми у́зами содержи́мии зря́ще, / к све́ту идя́ху, Христе́, / весе́лыми нога́ми, / Па́сху хва́ляще ве́чную. Припев:"},
  {"id": "cu-sve-0086", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0087", "section": "service", "who": "choir", "text": "Присту́пим свещено́снии, / исходя́щу Христу́ из гро́ба, я́ко жениху́, / и спра́зднуем любопра́зднственными чи́нми / Па́сху Бо́жию спаси́тельную. Катавасия:"},
  {"id": "cu-sve-0088", "section": "service", "who": "choir", "text": "У́тренюем у́треннюю глубоку́: И тропарь:"},
  {"id": "cu-sve-0089", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0090", "section": "service", "who": "rubric", "text": "Ектениа, и возглас:"},
  {"id": "cu-sve-0091", "section": "service", "who": "choir", "text": "Я́ко святи́ся и просла́вися пречестно́е и великоле́пое и́мя Твое́, Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0092", "section": "service", "who": "choir", "text": "Песнь 6. Ирмос:"},
  {"id": "cu-sve-0093", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́, / и сокруши́л еси́ вереи́ ве́чныя, / содержа́щия свя́занныя, Христе́, / и тридне́вен, я́ко от ки́та Ио́на, / воскре́сл еси́ от гро́ба. Припев:"},
  {"id": "cu-sve-0094", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0095", "section": "service", "who": "choir", "text": "Сохрани́в це́ла зна́мения, Христе́, / воскре́сл еси́ от гро́ба, / ключи́ Де́вы не вреди́вый в рождестве́ Твое́м, / и отве́рзл еси́ нам ра́йския две́ри. Припев:"},
  {"id": "cu-sve-0096", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0097", "section": "service", "who": "choir", "text": "Спа́се мой, / живо́е же и неже́ртвенное заколе́ние, / я́ко Бог Сам Себе́ / во́лею приве́д Отцу́, / совоскреси́л еси́ всеро́днаго Ада́ма, / воскре́с от гро́ба. Катавасия:"},
  {"id": "cu-sve-0098", "section": "service", "who": "choir", "text": "Снизше́л еси́ в преиспо́дняя земли́: И тропарь:"},
  {"id": "cu-sve-0099", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0100", "section": "service", "who": "rubric", "text": "Ектениа, и возглас:"},
  {"id": "cu-sve-0101", "section": "service", "who": "choir", "text": "Ты бо еси́ Царь ми́ра, и Спас душ на́ших, и Тебе́ сла́ву возсыла́ем, Отцу́ и Сы́ну и Свято́му Ду́ху, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0102", "section": "service", "who": "choir", "text": "Таже кондак, глас 8:"},
  {"id": "cu-sve-0103", "section": "service", "who": "choir", "text": "А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко победитель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся, / и Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние. Икос:"},
  {"id": "cu-sve-0104", "section": "service", "who": "choir", "text": "Е́же пре́жде со́лнца Со́лнце заше́дшее иногда́ во гроб, / предвари́ша ко у́тру, и́щущия я́ко дне мvроно́сицы де́вы, / и друга́ ко друзе́й вопия́ху: / о други́ни! Прииди́те, воня́ми пома́жем те́ло живоно́сное и погребе́ное, / плоть воскреси́вшаго па́дшаго Ада́ма, лежа́щую во гро́бе. / И́дем, потщи́мся я́коже волсви́, и поклони́мся, / и принесе́м мvра я́ко да́ры, не в пелена́х, но в плащани́це обви́тому, / и пла́чим, и возопии́м: о Влады́ко, воста́ни, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-sve-0105", "section": "service", "who": "choir", "text": "Синаксарий, во святую и великую неделю Пасхи."},
  {"id": "cu-sve-0106", "section": "service", "who": "choir", "text": "Стихи: Христо́с сшед к борьбе́ а́дове Еди́н. Мно́гия взем побе́ды коры́сти, взы́де."},
  {"id": "cu-sve-0107", "section": "service", "who": "choir", "text": "Во святу́ю и вели́кую Неде́лю Па́схи са́мое живоно́сное Воскресе́ние пра́зднуем Го́спода Бо́га и Спа́са на́шего Иису́са Христа́,"},
  {"id": "cu-sve-0108", "section": "service", "who": "choir", "text": "е́же у́бо и Па́сху имену́ем, я́же евре́йскою бесе́дою преведе́ние толку́ется. Той бо есть день, во́ньже Бог в нача́ле мiр от небытия́ приведе́. В той день изра́ильтеския лю́ди, сквозе́ Чермно́е мо́ре прове́д, от фарао́новых исхища́ет рук. В той па́ки, с небесе́ соше́д, во утро́бу Де́вы всели́ся, и ны́не из а́довых сокро́вищ челове́ческое естество́ все исхити́в, на небеса́ возведе́ и к дре́внему достоя́нию приведе́ нетле́ния. Оба́че, соше́д во ад, не всех воскреси́, но ели́цы ве́ровати Ему́ изво́лиша, ду́ши же я́же от ве́ка святы́х ну́ждею держи́мыя от а́да свободи́, и всем даде́ на небеса́ взы́ти. Сего́ ра́ди, ра́дующеся, преесте́ственне со све́тлостию Воскресе́ние пра́зднуем, ра́дость образу́юще, е́юже естество́ на́ше милосе́рдия ра́ди ми́лости Бо́жия обогати́ся; та́кожде и вражды́ разруше́ние, и е́же с Бо́гом соедине́ние и с саме́ми А́нгелы показу́юще, обы́чное содева́ем целова́ние."},
  {"id": "cu-sve-0109", "section": "service", "who": "choir", "text": "Госпо́дне же Воскресе́ние бысть си́це: во́ином стрегу́щим гроб, о полу́нощи трус быва́ет, соше́д бо А́нгел, ка́мень отваля́ет от две́рей гро́ба, cтра́жие же ужаса́ющеся бе́гают. И прихожде́ние зде жена́м быва́ет в суббо́ту по́зде, я́коже от полсуббо́тныя но́щи. И пе́рвее у́бо Воскресе́ние Бо́жии Ма́тери познава́емо быва́ет пря́мо седя́щей гро́ба с Магдали́нею, я́коже глаго́лет Матфе́й. Но да не сомни́ло бы ся Воскресе́ние, за е́же к Ма́тери присвое́ния, евангели́сти глаго́лют: пе́рвее явля́ется Магдали́ни Мари́и, она́ же и на ка́мени А́нгела ви́де, и прини́кши па́ки су́щия внутрь зрит, и́же у́бо и Госпо́дне Воскресе́ние возвеща́ют: воста́ бо, глаго́лют, несть зде, се ме́сто, иде́же положи́ша Его́. Тече́т у́бо сия́ слы́шавши и к тепле́йшим от учени́к прихо́дит, к Петру́ и Иоа́нну, и Воскресе́ние сим благовеству́ет. Возвраща́ющися же ей с друго́ю Мари́ею, сре́те я́ Христо́с, глаго́ля: ра́дуйтеся. Подоба́ше бо пе́рвее слы́шавшему ро́ду: в печа́лех роди́ши ча́да, тому́ пре́жде и ра́дость внуши́ти. Сия́ же любо́вию побежда́емыя приступа́ют и пречи́стыма нога́ма Его́ каса́ются, опа́снейше разуме́ти хотя́ше. Апо́стола же ко гро́бу притеко́ста, Иоа́нн у́бо прини́к то́чию во гроб, оты́де. Петр же внутрь вхо́дит и испы́тнейше зрит, плащани́це же каса́ется и сударе́ви."},
  {"id": "cu-sve-0110", "section": "service", "who": "choir", "text": "Па́ки же Магдали́на прихо́дит ко гро́бу о у́трени со други́ми жена́ми, ви́денная уве́рити хотя́щи опа́сне. У вне́шних же стоя́щи рыда́ше, внутрь же гро́ба прини́кши, зрит два А́нгела блиста́ющася све́тлостию, и а́ки претя́ща ей, и глаго́люща: же́но, что пла́чеши и кого́ и́щеши? Иису́са и́щете Назаряни́на распя́таго, воста́, несть зде. И а́бие воста́ша пристра́шни, ви́девше Го́спода. Те́мже она́, обра́щшися вспять, ви́дит Христа́ стоя́ща, вертогра́даря же Его́ бы́ти мня́щи (зане́ в вертогра́де гроб бысть), глаго́лет: го́споди, а́ще ты еси́ взял Его́, рцы ми, где еси́ положи́л Его́ и аз возму́ Его́. Па́ки же Спас, ко А́нгелом помаа́в, глаго́лет к Магдали́ни: Мари́е. Она́ же сла́дкий и обы́чный Христо́в ощути́вши глас, прикосну́тися Ему́ хотя́ше. Он же глаго́лет: не прикаса́йся Мне, не у́бо взыдо́х ко Отцу́ Моему́, я́коже ты помышля́еши, еще́ челове́ка Мя бы́ти непщу́ющи, иди́ же к бра́тии Мое́й и рцы им, ели́ка же ви́дела еси́ и слы́шала. И сие́ у́бо Магдали́на де́лает. Свита́ющу же дню па́ки у гро́ба с про́чими быва́ет. Су́щии же со Иоа́нною и Саломи́ею, возсия́вшу со́лнцу приидо́ша. И про́сто рещи́, разли́чно е́же на гроб жен прихожде́ние бысть, в ни́хже бе и Богоро́дица, Та бо есть, ю́же Иоси́еву глаго́лет Мари́ю Ева́нгелие. Ио́сифов же бе сын сей Иоси́й. В неизве́стном у́бо есть, в кий час воскре́се Госпо́дь: не́цыи у́бо в пе́рвое куроглаше́ние глаго́лют, друзи́и же егда́ трус бысть, и разли́чно друзи́и."},
  {"id": "cu-sve-0111", "section": "service", "who": "choir", "text": "Сим же та́ко бы́вшим, се не́ции от кустоди́и доше́дше, возвести́ша архиере́ем соде́явшаяся. Они́ же сре́брениками их умзди́вше, повину́ют рещи́, я́ко ученицы́ Его́, прише́дше но́щию, украдо́ша Его́. В ве́чер настоя́щаго дне, ученико́м во еди́но собра́ным стра́ха ра́ди иуде́йскаго и две́рем тве́рдо заключе́ным, вхо́дит к ним Иису́с, я́ко в нетле́ннем телеси́ бе, и мир обы́чно сим благовеству́ет. Они́ же, Сего́ ви́девше, премно́го возра́довашася, и дунове́нием соверше́ннейшее Всесвята́го Ду́ха де́йство прие́млют."},
  {"id": "cu-sve-0112", "section": "service", "who": "choir", "text": "Ка́ко же тридне́вное Воскресе́ние Госпо́дне? Веждь си́це: ве́чер четвертка́ и день пятка́, та́ко бо нощеде́нство евре́е исчита́ют, день еди́н. Пятка́ па́ки нощь и суббо́та вся, друго́е нощеде́нство, се день вторы́й. Па́ки суббо́тная нощь и неде́ли день, от ча́сти бо нача́ла все прие́млется, тре́тие нощеде́нство, се день тре́тий. Или́ си́це: в тре́тий час пятка́ ра́спят бысть Христо́с. Та́же от шеста́го часа́ до девя́таго тма бысть, сие́ нощь ми разуме́й, се от тре́тияго да́же до девя́таго еди́но нощеде́нство. Та́же па́ки по тьме, день и нощь пятка́, се два нощеде́нства. День суббо́ты и нощь ея́ па́ки, се три нощеде́нства, по Евангели́сту глаго́лющему: свита́ющу во еди́ну от суббо́т. А́ще ли в тре́тий обеща́в облагоде́тельствова нас Спас, скоре́йше соде́ла благоде́йство. И та́ко благода́ть, и сла́ва Ему́ во ве́ки веко́в. Ами́нь."},
  {"id": "cu-sve-0113", "section": "service", "who": "choir", "text": "Таже глаголем:"},
  {"id": "cu-sve-0114", "section": "service", "who": "choir", "text": "Воскресе́ние Христо́во ви́девше, / поклони́мся Свято́му Го́споду Иису́су, / еди́ному безгре́шному. / Кресту́ Твоему́ покланя́емся, Христе́, / и свято́е Воскресе́ние Твое́ пое́м и сла́вим. / Ты бо еси́ Бог наш, / ра́зве Тебе́ ино́го не зна́ем, / и́мя Твое́ имену́ем. / Прииди́те, вси ве́рнии, / поклони́мся Свято́му Христо́ву Воскресе́нию: / се бо прии́де Кресто́м ра́дость всему́ ми́ру. / Всегда́ благословя́ще Го́спода, / пое́м Воскресе́ние Его́: / распя́тие бо претерпе́в, / сме́ртию смерть разруши́. [Трижды.]"},
  {"id": "cu-sve-0115", "section": "service", "who": "choir", "text": "Воскре́с Иису́с от гро́ба, / я́коже прорече́, / даде́ нам живо́т ве́чный / и ве́лию ми́лость. [Трижды.]"},
  {"id": "cu-sve-0116", "section": "service", "who": "choir", "text": "Песнь 7. Ирмос:"},
  {"id": "cu-sve-0117", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый, / быв Челове́к, / стра́ждет я́ко сме́ртен, / и стра́стию сме́ртное, / в нетле́ния облачи́т благоле́пие, / Еди́н благослове́н / отце́в Бог и препросла́влен. Припев:"},
  {"id": "cu-sve-0118", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0119", "section": "service", "who": "choir", "text": "Жены́ с ми́ры богому́дрыя в след Тебе́ теча́ху, / Его́же, я́ко ме́ртва, со слеза́ми иска́ху, / поклони́шася ра́дующияся Живо́му Бо́гу, / и Па́сху та́йную / Твои́м, Христе́, ученико́м благовести́ша. Припев:"},
  {"id": "cu-sve-0120", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0121", "section": "service", "who": "choir", "text": "Сме́рти пра́зднуем умерщвле́ние, / а́дово разруше́ние, / ино́го жития́ ве́чнаго нача́ло, / и игра́юще пое́м Вино́внаго, / Еди́наго благослове́ннаго / отце́в Бо́га и препросла́вленнаго. Припев:"},
  {"id": "cu-sve-0122", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0123", "section": "service", "who": "choir", "text": "Я́ко вои́стинну свяще́нная, / и всепра́зднственная сия́ спаси́тельная нощь, / и светоза́рная, / светоно́снаго дне, / воста́ния су́щи провозве́стница, / в не́йже безле́тный Свет из гро́ба пло́тски всем возсия́. Катавасия:"},
  {"id": "cu-sve-0124", "section": "service", "who": "choir", "text": "О́троки от пе́щи изба́вивый: И тропарь:"},
  {"id": "cu-sve-0125", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0126", "section": "service", "who": "rubric", "text": "Ектениа, и возглас:"},
  {"id": "cu-sve-0127", "section": "service", "who": "choir", "text": "Бу́ди держа́ва Ца́рствия Твоего́ благослове́нна и препросла́вленна, Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0128", "section": "service", "who": "choir", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-sve-0129", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день, / Еди́н суббо́т Царь и Госпо́дь, / пра́здников пра́здник / и торжество́ есть торже́ств, / во́ньже благослови́м Христа́ во ве́ки. Припев:"},
  {"id": "cu-sve-0130", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0131", "section": "service", "who": "choir", "text": "Прииди́те, но́ваго виногра́да рожде́ния, / Боже́ственнаго весе́лия, / в наро́читом дни Воскресе́ния, / Ца́рствия Христо́ва приобщи́мся, / пою́ще Его́ / я́ко Бо́га во ве́ки. Припев:"},
  {"id": "cu-sve-0132", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых."},
  {"id": "cu-sve-0133", "section": "service", "who": "choir", "text": "Возведи́ о́крест о́чи твои́, Сио́не, и виждь: / се бо приидо́ша к тебе́, / я́ко богосве́тлая свети́ла, / от за́пада, и се́вера, и мо́ря, / и восто́ка ча́да твоя́, / в тебе́ благословя́щая Христа́ во ве́ки. Припев:"},
  {"id": "cu-sve-0134", "section": "service", "who": "choir", "text": "Пресвята́я Тро́ице, Бо́же наш, сла́ва Тебе́. Троичен:"},
  {"id": "cu-sve-0135", "section": "service", "who": "choir", "text": "О́тче Вседержи́телю, и Сло́ве, и Ду́ше, / треми́ соединя́емое во Ипоста́сех Естество́, / Пресу́щественне и Пребоже́ственне, / в Тя крести́хомся, / и Тя благослови́м во вся ве́ки. Катавасия:"},
  {"id": "cu-sve-0136", "section": "service", "who": "choir", "text": "Сей нарече́нный и святы́й день: И тропарь:"},
  {"id": "cu-sve-0137", "section": "service", "who": "choir", "text": "Xристос воскре́се: трижды."},
  {"id": "cu-sve-0138", "section": "service", "who": "rubric", "text": "Таже ектениа, и возглас:"},
  {"id": "cu-sve-0139", "section": "service", "who": "choir", "text": "Я́ко благослови́ся и́мя Твое́, и просла́вися Ца́рство Твое́, Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0140", "section": "service", "who": "choir", "text": "Песнь 9."},
  {"id": "cu-sve-0141", "section": "service", "who": "deacon", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба / Христа́ Жизнодавца."},
  {"id": "cu-sve-0142", "section": "service", "who": "rubric", "text": "Таже первый лик поет ирмос:"},
  {"id": "cu-sve-0143", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-sve-0144", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и ирмос."},
  {"id": "cu-sve-0145", "section": "service", "who": "rubric", "text": "Таже первый лик поет вторый припев:"},
  {"id": "cu-sve-0146", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / во́лею страда́вша, и погребе́на, / и Воскре́сшаго тридне́вно от гро́ба. И ирмос:"},
  {"id": "cu-sve-0147", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся:"},
  {"id": "cu-sve-0148", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев, и ирмос."},
  {"id": "cu-sve-0149", "section": "service", "who": "rubric", "text": "Таже первый лик поет третий припев:"},
  {"id": "cu-sve-0150", "section": "service", "who": "choir", "text": "Христо́с но́вая Па́сха, / Же́ртва жива́я, / А́гнец Бо́жий, / взе́мляй грехи́ ми́ра."},
  {"id": "cu-sve-0151", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго, / о сладча́йшаго Твоего́ гла́са! / С на́ми бо нело́жно / обеща́лся еси́ бы́ти, / до сконча́ния ве́ка, Христе́. / Его́же, ве́рнии, / утвержде́ние наде́жди иму́ще, ра́дуемся."},
  {"id": "cu-sve-0152", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и стих."},
  {"id": "cu-sve-0153", "section": "service", "who": "rubric", "text": "Таже первый лик поет четвертый припев:"},
  {"id": "cu-sve-0154", "section": "service", "who": "choir", "text": "А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый, / лю́дие, весели́теся. И тропарь:"},
  {"id": "cu-sve-0155", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-sve-0156", "section": "service", "who": "choir", "text": "И вторый лик поет тойже припев и стих."},
  {"id": "cu-sve-0157", "section": "service", "who": "rubric", "text": "Таже первый лик:"},
  {"id": "cu-sve-0158", "section": "service", "who": "choir", "text": "Возбуди́л еси́ усну́в ме́ртвыя от ве́ка, / ца́рски рыка́вый, я́ко от Иу́ды лев. И тропарь:"},
  {"id": "cu-sve-0159", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-sve-0160", "section": "service", "who": "rubric", "text": "И вторый лик:"},
  {"id": "cu-sve-0161", "section": "service", "who": "choir", "text": "Магдали́на Мари́я притече́ ко гро́бу, / и Христа́ ви́девши, / я́ко вертогра́даря вопроша́ше. И тропарь:"},
  {"id": "cu-sve-0162", "section": "service", "who": "choir", "text": "О, Боже́ственнаго, о любе́знаго:"},
  {"id": "cu-sve-0163", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-sve-0164", "section": "service", "who": "choir", "text": "А́нгел облиста́яй жена́м вопия́ше: / преста́ните от слез, я́ко Христо́с воскре́се."},
  {"id": "cu-sve-0165", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая, Христе́! / О му́дросте, и Сло́ве Бо́жий, и си́ло! / Подава́й нам и́стее Тебе́ причаща́тися, / в невече́рнем дни Ца́рствия Твоего́."},
  {"id": "cu-sve-0166", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sve-0167", "section": "service", "who": "choir", "text": "Христо́с воскре́се, смерть попра́вый, / и ме́ртвыя воздви́гнувый, / лю́дие весели́теся. И тропарь:"},
  {"id": "cu-sve-0168", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sve-0169", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-sve-0170", "section": "service", "who": "choir", "text": "Днесь вся́ка тварь весели́тся и ра́дуется, / я́ко Христо́с воскре́се и ад плени́ся. И тропарь:"},
  {"id": "cu-sve-0171", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sve-0172", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sve-0173", "section": "service", "who": "choir", "text": "Днесь Влады́ка плени́ а́да, / воздви́гнувый ю́зники, я́же от ве́ка имя́ше лю́те одержи́мыя. И тропарь:"},
  {"id": "cu-sve-0174", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sve-0175", "section": "service", "who": "rubric", "text": "Первый лик:"},
  {"id": "cu-sve-0176", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Триипоста́снаго и Неразде́льнаго Божества́ держа́ву. И тропарь:"},
  {"id": "cu-sve-0177", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sve-0178", "section": "service", "who": "rubric", "text": "Вторый лик:"},
  {"id": "cu-sve-0179", "section": "service", "who": "choir", "text": "Ра́дуйся, Де́во, ра́дуйся, / ра́дуйся, Благослове́нная, / ра́дуйся, Препросла́вленная! / Твой бо Сын воскре́се тридне́вен от гро́ба. И тропарь:"},
  {"id": "cu-sve-0180", "section": "service", "who": "choir", "text": "О, Па́сха ве́лия и свяще́ннейшая:"},
  {"id": "cu-sve-0181", "section": "service", "who": "rubric", "text": "Последи же первый лик поет паки первый припев:"},
  {"id": "cu-sve-0182", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / Воскре́сшаго тридне́вно от гро́ба / Христа́ Жизнодавца. И ирмос:"},
  {"id": "cu-sve-0183", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-sve-0184", "section": "service", "who": "rubric", "text": "И вторый лик поет паки вторый припев:"},
  {"id": "cu-sve-0185", "section": "service", "who": "choir", "text": "Вели́чит душа́ моя́ / во́лею страда́вша, и погребе́на, / и Воскре́сшаго тридне́вно от гро́ба. И ирмос:"},
  {"id": "cu-sve-0186", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся:"},
  {"id": "cu-sve-0187", "section": "service", "who": "rubric", "text": "Таже оба лика, сошедшеся вкупе, поют ирмос:"},
  {"id": "cu-sve-0188", "section": "service", "who": "choir", "text": "Свети́ся, свети́ся: и тропарь:"},
  {"id": "cu-sve-0189", "section": "service", "who": "choir", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sve-0190", "section": "service", "who": "rubric", "text": "Ектениа, и возглас:"},
  {"id": "cu-sve-0191", "section": "service", "who": "choir", "text": "Я́ко Тя хва́лят вся Си́лы Небе́сныя, Отца́ и Сы́на и Свята́го Ду́ха, и Тебе́ сла́ву возсылают, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0192", "section": "service", "who": "choir", "text": "Ексапостиларий. Самогласен:"},
  {"id": "cu-sve-0193", "section": "service", "who": "choir", "text": "Пло́тию усну́в, / я́ко мертв, / Царю́ и Го́споди, / тридне́вен воскре́сл еси́, / Ада́ма воздви́г от тли, / и упраздни́в смерть, / Па́сха нетле́ния, / ми́ра спасе́ние. [Трижды.]"},
  {"id": "cu-sve-0194", "section": "service", "who": "choir", "text": "На хвалитех, Всякое дыхание: на глас 1. Поставим стихи 4, и поем стихиры воскресны, глас 1: Стих:"},
  {"id": "cu-sve-0195", "section": "service", "who": "choir", "text": "Хвали́те Его́ на си́лах Его́, / хвали́те Его́ по мно́жеству вели́чествия Его́."},
  {"id": "cu-sve-0196", "section": "service", "who": "choir", "text": "Пое́м Твою́, Христе́, спаси́тельную страсть, / и сла́вим Твое́ Воскресе́ние. Стих:"},
  {"id": "cu-sve-0197", "section": "service", "who": "choir", "text": "Хвали́те Его́ во гла́се тру́бнем, / хвалите Его́ во псалти́ри и гу́слех."},
  {"id": "cu-sve-0198", "section": "service", "who": "choir", "text": "Крест претерпе́вый, и смерть упраздни́вый, / и воскресы́й из ме́ртвых, / умири́ на́шу жизнь, Го́споди, / я́ко Еди́н Всеси́лен. Стих:"},
  {"id": "cu-sve-0199", "section": "service", "who": "choir", "text": "Хвали́те Его́ в тимпа́не и ли́це, / хвали́те Его́ во стру́нах и орга́не."},
  {"id": "cu-sve-0200", "section": "service", "who": "choir", "text": "А́да плени́вый и челове́ка воскреси́вый, / Воскресе́нием Твои́м, Христе́, / сподо́би ны чи́стым се́рдцем, / Тебе́ пе́ти и сла́вити. Стих:"},
  {"id": "cu-sve-0201", "section": "service", "who": "choir", "text": "Хвали́те Его́ в кимва́лех доброгла́сных, хвали́те Его́ в кимва́лех восклица́ния, / вся́кое дыха́ние да хва́лит Го́спода."},
  {"id": "cu-sve-0202", "section": "service", "who": "choir", "text": "Боголе́пное Твое́ снизхожде́ние сла́вяще, / пое́м Тя, Христе́: / роди́лся еси́ от Де́вы, / и неразлуче́н был еси́ от Отца́: / пострада́л еси́ я́ко челове́к, / и во́лею претерпе́л еси́ Крест, / воскре́сл еси́ от гро́ба я́ко от черто́га произше́д, / да спасе́ши мир, / Го́споди, сла́ва Тебе́."},
  {"id": "cu-sve-0203", "section": "service", "who": "choir", "text": "Таже совокупльшеся оба лика, поют стихиры Пасхи. Глас 5. Стих:"},
  {"id": "cu-sve-0204", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, / и расточа́тся врази́ Его́."},
  {"id": "cu-sve-0205", "section": "service", "who": "choir", "text": "Па́сха / свяще́нная нам днесь показа́ся; / Па́сха но́ва свята́я; / Па́сха та́инственная; / Па́сха всечестна́я. / Па́сха Христо́с Изба́витель; / Па́сха непоро́чная; / Па́сха вели́кая; / Па́сха ве́рных. / Па́сха две́ри ра́йския нам отверза́ющая. / Па́сха всех освяща́ющая ве́рных. Стих:"},
  {"id": "cu-sve-0206", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, / да исче́знут."},
  {"id": "cu-sve-0207", "section": "service", "who": "choir", "text": "Прииди́те / от виде́ния жены́ благове́стницы, / и Сио́ну рцы́те: / приими́ / от нас ра́дости благове́щения, Воскресе́ния Христо́ва: / красу́йся, лику́й / и ра́дуйся, Иерусали́ме, / Царя́ Христа́ узре́в из гро́ба, / я́ко жениха́ происходя́ща. Стих:"},
  {"id": "cu-sve-0208", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся."},
  {"id": "cu-sve-0209", "section": "service", "who": "choir", "text": "Мироно́сицы жены́, / у́тру глубоку́, / предста́вша гро́бу Живода́вца, / обрето́ша А́нгела / на ка́мени седя́ща, / и той провеща́в им, / си́це глаго́лаше: / что и́щете Жива́го с ме́ртвыми; / что пла́чете Нетле́ннаго во тли? / Ше́дше, пропове́дите ученико́м Его́. Стих:"},
  {"id": "cu-sve-0210", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори Госпо́дь, / возра́дуемся и возвесели́мся в онь."},
  {"id": "cu-sve-0211", "section": "service", "who": "choir", "text": "Па́сха кра́сная, / Па́сха, Госпо́дня Па́сха! / Па́сха всечестна́я / нам возсия́. Па́сха, / ра́достию друг дру́га обы́мем. / О Па́сха! / Избавле́ние ско́рби, / и́бо из гро́ба днесь, / я́ко от черто́га / возсия́в Христо́с, / жены́ ра́дости испо́лни, глаго́ля: / пропове́дите апо́столом."},
  {"id": "cu-sve-0212", "section": "service", "who": "choir", "text": "Слава, и ныне, глас 5: Воскресе́ния день, / и просвети́мся торжество́м, / и друг дру́га обы́мем. / Рцем бра́тие, / и ненави́дящим нас, / прости́м вся Воскресе́нием, / и та́ко возопии́м: / Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0213", "section": "service", "who": "choir", "text": "Таже настоящий тропарь, во глас 5, трижды: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0214", "section": "service", "who": "choir", "text": "И поем сие многажды, дондеже целуют братия друг друга."},
  {"id": "cu-sve-0215", "section": "service", "who": "rubric", "text": "Целование же настоятеля с прочими иереи и диаконы во святом алтари бывает сице: Глаголет приходяй:"},
  {"id": "cu-sve-0216", "section": "service", "who": "deacon", "text": "Христо́с воскре́се,"},
  {"id": "cu-sve-0217", "section": "service", "who": "rubric", "text": "оному же отвещавшу:"},
  {"id": "cu-sve-0218", "section": "service", "who": "deacon", "text": "Вои́стину воскре́се."},
  {"id": "cu-sve-0219", "section": "service", "who": "rubric", "text": "Посем взем настоятель Честный Крест и станет вне пред святыми царскими дверьми. Такожде и вси священницы, елико их есть, и диакони, вземше кийждо их святое Евангелие, и честные иконы, по чину своему: и станут вси рядом, от десныя страны настоятеля. И приходят прежде честнейшии церковницы и старцы, един по единому, и мало преклоняются пред настоятелем и целуют кийждо их Честный Крест и святое Евангелие, егоже держит иерей, и прочии образы. Таже и самого настоятеля во уста целуют, глаголюще:"},
  {"id": "cu-sve-0220", "section": "service", "who": "deacon", "text": "Христо́с воскре́се."},
  {"id": "cu-sve-0221", "section": "service", "who": "rubric", "text": "Оному же отвещавшу:"},
  {"id": "cu-sve-0222", "section": "service", "who": "deacon", "text": "Вои́стину воскре́се."},
  {"id": "cu-sve-0223", "section": "service", "who": "rubric", "text": "По томуже образу и иереев целуют, и сами между собою по чину своему. И ставятся от иереев по десной стране рядом. Таже по них и миряне такожде целование творят. Работницы же монастырстии в томже чину да станут и друг друга целующе. Бывает же посреди во всех велие молчание. По целовании же чтется Огласительное слово Златоустаго от настоятеля или екклисиарха: не седим же на сицевом чтении, но стояще слушаем вси."},
  {"id": "cu-sve-0224", "section": "service", "who": "deacon", "text": "Иже во святых отца нашего Иоанна, Архиепископа Константинопольскаго, Златоустаго, слово Огласительное во святый и светоносный день преславнаго и спасительнаго Христа Бога нашего Воскресения."},
  {"id": "cu-sve-0225", "section": "service", "who": "deacon", "text": "А́ще кто благочести́в и боголюби́в, да наслади́тся сего́ до́браго и све́тлаго торжества́. А́ще кто раб благоразу́мный, да вни́дет ра́дуяся в ра́дость Го́спода своего́. А́ще кто потруди́ся постя́ся, да восприи́мет ны́не дина́рий. А́ще кто от пе́рваго часа́ де́лал есть, да прии́мет днесь пра́ведный долг. А́ще кто по тре́тием часе́ прии́де, благодаря́ да пра́зднует. А́ще кто по шесто́м часе́ дости́же, ничто́же да сумни́тся, и́бо ничи́мже отщетева́ется. А́ще кто лиши́ся и девя́таго часа́, да присту́пит, ничто́же сумня́ся, ничто́же боя́ся. А́ще кто то́чию дости́же, и во единонадеся́тый час, да не устраши́тся замедле́ния: любочести́в бо Сый Влады́ка, прие́млет после́дняго я́коже и пе́рваго: упокоева́ет в единонадеся́тый час прише́дшаго, я́коже де́лавшаго от пе́рваго часа́. И после́дняго ми́лует, и пе́рвому угожда́ет, и о́ному дае́т, и сему́ да́рствует, и дела́ прие́млет, и наме́рение целу́ет, и дея́ние почита́ет, и предложе́ние хва́лит. Те́мже у́бо вни́дите вси в ра́дость Го́спода своего́: и пе́рвии и втори́и, мзду приими́те. Бога́тии и убо́зии, друг со дру́гом лику́йте. Возде́ржницы и лени́вии, день почти́те. Пости́вшиися и непости́вшиися, возвесели́теся днесь. Трапе́за испо́лнена, наслади́теся вси. Теле́ц упита́нный, никто́же да изы́дет а́лчай, вси наслади́теся пи́ра ве́ры: вси восприими́те бога́тство бла́гости. Никто́же да рыда́ет убо́жества, яви́ся бо о́бщее Ца́рство. Никто́же да пла́чет прегреше́ний, проще́ние бо от гро́ба возсия́. Никто́же да убои́тся сме́рти, свободи́ бо нас Спа́сова смерть. Угаси́ ю́, И́же от нея́ держи́мый. Плени́ а́да, Соше́дый во ад. Огорчи́ его́ вкуси́вша пло́ти Его́. И сие́ предприе́мый Иса́иа возопи́: ад, глаго́лет, огорчи́ся, срет Тя до́ле. Огорчи́ся, и́бо упраздни́ся. Огорчи́ся, и́бо пору́ган бысть. Огорчи́ся, и́бо умертви́ся. Огорчи́ся, и́бо низложи́ся. Огорчи́ся, и́бо связа́ся. Прия́т те́ло, и Бо́гу прирази́ся. Прия́т зе́млю, и сре́те Не́бо. Прия́т е́же ви́дяше, и впаде́ во е́же не ви́дяше. Где твое́, сме́рте, жа́ло; где твоя́, а́де, побе́да? Воскре́се Христо́с, и ты низве́рглся еси́. Воскре́се Христо́с, и падо́ша де́мони. Воскре́се Христо́с, и ра́дуются А́нгели. Воскре́се Христо́с, и жизнь жи́тельствует. Воскре́се Христо́с, и ме́ртвый ни еди́н во гро́бе. Христо́с бо воста́в от ме́ртвых, Нача́ток усо́пших бысть. Тому́ сла́ва и держа́ва, во ве́ки веко́в. Ами́нь."},
  {"id": "cu-sve-0226", "section": "service", "who": "deacon", "text": "Таже глаголется тропарь святаго. Глас 8:"},
  {"id": "cu-sve-0227", "section": "service", "who": "deacon", "text": "Уст твои́х, я́коже све́тлость огня́ / возсия́вши, благода́ть вселе́нную просвети́: / не сребролю́бия ми́рови сокро́вища сниска́, / высоту́ нам смиреному́дрия показа́, / но твои́ми словесы́ наказу́я, о́тче Иоа́нне Златоу́сте, / моли́ Сло́ва, Христа́ Бо́га, спасти́ся душа́м на́шим."},
  {"id": "cu-sve-0228", "section": "service", "who": "deacon", "text": "Посем диакон глаголет ектении: Поми́луй нас, Бо́же: и Испо́лним у́треннюю моли́тву на́шу Го́сподеви."},
  {"id": "cu-sve-0229", "section": "service", "who": "rubric", "text": "И по возгласе, диакон:"},
  {"id": "cu-sve-0230", "section": "service", "who": "deacon", "text": "Прему́дрость. Мы же:"},
  {"id": "cu-sve-0231", "section": "service", "who": "deacon", "text": "Благослови́. Настоятель:"},
  {"id": "cu-sve-0232", "section": "service", "who": "deacon", "text": "Сый благослове́н Христо́с Бог наш, всегда́, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-sve-0233", "section": "service", "who": "deacon", "text": "Ами́нь. Утверди́, Бо́же, святу́ю правосла́вную ве́ру, правосла́вных христиа́н во ве́к ве́ка."},
  {"id": "cu-sve-0234", "section": "service", "who": "rubric", "text": "Посем настоятель, держа Крест, вместо: Слава Тебе, Христе Боже: поет:"},
  {"id": "cu-sve-0235", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. И мы поем:"},
  {"id": "cu-sve-0236", "section": "service", "who": "deacon", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0237", "section": "service", "who": "choir", "text": "Отпуст: Христо́с воскресы́й из ме́ртвых, сме́ртию смерть попра́вый и су́щим во гробе́х живо́т дарова́вый: и́стинный Бог наш, моли́твами Пречи́стыя Своея́ Ма́тере и всех святы́х, поми́лует и спасе́т нас, я́ко Благ и Человеколю́бец."},
  {"id": "cu-sve-0238", "section": "service", "who": "rubric", "text": "Таже, Крест возвышая, глаголет:"},
  {"id": "cu-sve-0239", "section": "service", "who": "choir", "text": "Христо́с воскре́се. Трижды."},
  {"id": "cu-sve-0240", "section": "service", "who": "rubric", "text": "Мы же отвещаем:"},
  {"id": "cu-sve-0241", "section": "service", "who": "choir", "text": "Вои́стинну воскре́се. Трижды."},
  {"id": "cu-sve-0242", "section": "service", "who": "rubric", "text": "Таже поем конечное:"},
  {"id": "cu-sve-0243", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0244", "section": "service", "who": "rubric", "text": "трижды, весь тропарь. И по нем пением кончим:"},
  {"id": "cu-sve-0245", "section": "service", "who": "choir", "text": "И нам дарова́ живо́т ве́чный, / покланя́емся Его́ тридне́вному Воскресе́нию."},
  {"id": "cu-sve-0246", "section": "service", "who": "choir", "text": "Вели́каго господи́на и отца́ на́шего [имярек]"},
  {"id": "cu-sve-0247", "section": "service", "who": "choir", "text": "Святе́йшаго Патриа́рха Моско́вскаго и всея́ Руси́, и господи́на на́шего преосвяще́ннейшаго [имярек],"},
  {"id": "cu-sve-0248", "section": "service", "who": "choir", "text": "митрополи́та (или архиепи́скопа, или епи́скопа егоже есть область),"},
  {"id": "cu-sve-0249", "section": "service", "who": "choir", "text": "Богохрани́мую страну́ на́шу Росси́йскую, настоя́теля, бра́тию, прихо́жан свята́го хра́ма сего́, и вся правосла́вныя христиа́ны, Го́споди, сохрани́ их на мно́гая ле́та."},
  {"id": "cu-sve-0250", "section": "service", "who": "rubric", "text": "И целуем Честный Крест, держимый в руку настоятеля."},
  {"id": "cu-sve-0251", "section": "service", "who": "rubric", "text": "И час первый. Глаголем:"},
  {"id": "cu-sve-0252", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0253", "section": "service", "who": "rubric", "text": "трижды. И прочее, якоже ниже указ есть о часех светлыя седмицы. Лития же в сий день не бывает."},
  {"id": "cu-sve-0254", "section": "service", "who": "choir", "text": "О ЧАСЕХ СВЯТЫЯ ПАСХИ И ВСЕЯ СВЕТЛЫЯ СЕДМИЦЫ"},
  {"id": "cu-sve-0255", "section": "service", "who": "choir", "text": "Подобает ведати, яко от сего дне святыя и великия Недели Пасхи даже до субботы, часы сице поются."},
  {"id": "cu-sve-0256", "section": "service", "who": "rubric", "text": "Наченшу иерею:"},
  {"id": "cu-sve-0257", "section": "service", "who": "choir", "text": "Благослове́н Бог наш всегда́, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-sve-0258", "section": "service", "who": "choir", "text": "Ами́нь. Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-sve-0259", "section": "service", "who": "priest", "text": "Таже глаголем трижды:"},
  {"id": "cu-sve-0260", "section": "service", "who": "priest", "text": "Воскресе́ние Христо́во ви́девше, / поклони́мся Свято́му Го́споду Иису́су, / еди́ному безгре́шному, / Кресту́ Твоему́ покланя́емся, Христе́, / и свято́е Воскресе́ние Твое́ пое́м и сла́вим. / Ты бо еси́ Бог наш, / ра́зве Тебе́ ино́го не зна́ем, / и́мя Твое́ имену́ем. / Прииди́те вси ве́рнии, / поклони́мся Свято́му Христо́ву Воскресе́нию, / се бо прии́де Кресто́м ра́дость всему́ ми́ру. / Всегда́ благословя́ще Го́спода, / пое́м Воскресе́ние Его́: / распя́тие бо претерпе́в, / сме́ртию смерть разруши́."},
  {"id": "cu-sve-0261", "section": "service", "who": "priest", "text": "Таже ипакои, глас 4, единощи:"},
  {"id": "cu-sve-0262", "section": "service", "who": "priest", "text": "Предвари́вшия у́тро, я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-sve-0263", "section": "service", "who": "priest", "text": "Таже кондак, глас 8, единощи:"},
  {"id": "cu-sve-0264", "section": "service", "who": "priest", "text": "А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу / и воскре́сл еси́, я́ко Победи́тель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся! / И Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-sve-0265", "section": "service", "who": "priest", "text": "Таже и сей тропарь единощи:"},
  {"id": "cu-sve-0266", "section": "service", "who": "priest", "text": "Во гро́бе пло́тски, во а́де же с душе́ю я́ко Бог, / в раи́ же с разбо́йником и на Престо́ле был еси́, Христе́, со Отце́м и Ду́хом, / вся исполня́яй, неопи́санный."},
  {"id": "cu-sve-0267", "section": "service", "who": "priest", "text": "Слава: Я́ко Живоно́сец, я́ко рая́ красне́йший, / вои́стину и черто́га вся́каго ца́рскаго показа́ся светле́йший, Христе́, гроб Твой, / исто́чник на́шего воскресе́ния."},
  {"id": "cu-sve-0268", "section": "service", "who": "priest", "text": "И ныне, Богородичен: Вы́шняго освяще́нное Боже́ственное селе́ние, ра́дуйся. / Тобо́ю бо даде́ся ра́дость, Богоро́дице, зову́щим: / благослове́нна Ты в жена́х еси́, Всенепоро́чная Влады́чице. Таже"},
  {"id": "cu-sve-0269", "section": "service", "who": "priest", "text": "Го́споди, поми́луй, 40."},
  {"id": "cu-sve-0270", "section": "service", "who": "priest", "text": "Слава, и ныне:"},
  {"id": "cu-sve-0271", "section": "service", "who": "priest", "text": "Честне́йшую Херуви́м / и сла́внейшую без сравне́ния Серафи́м, / без истле́ния Бо́га Сло́ва ро́ждшую, / су́щую Богоро́дицу, Тя велича́ем."},
  {"id": "cu-sve-0272", "section": "service", "who": "priest", "text": "И́менем Госпо́дним благослови́, о́тче."},
  {"id": "cu-sve-0273", "section": "service", "who": "priest", "text": "Моли́твами святы́х оте́ц на́ших, Го́споди Иису́се Христе́, Бо́же наш, поми́луй нас. Мы же речем:"},
  {"id": "cu-sve-0274", "section": "service", "who": "priest", "text": "Ами́нь."},
  {"id": "cu-sve-0275", "section": "service", "who": "rubric", "text": "И паки глаголем подобне:"},
  {"id": "cu-sve-0276", "section": "service", "who": "priest", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-sve-0277", "section": "service", "who": "priest", "text": "Сла́ва, и ны́не: Го́споди, поми́луй, трижды."},
  {"id": "cu-sve-0278", "section": "service", "who": "priest", "text": "Благослови́."},
  {"id": "cu-sve-0279", "section": "service", "who": "priest", "text": "И отпуст перваго часа."},
  {"id": "cu-sve-0280", "section": "service", "who": "rubric", "text": "Сим же образом поется за третий, за шестый, пред литургиею. Такожде и пред вечернею, за девятый час: и за повечерие единожды. Такожде и за полунощницу. Аще ли не будет когда по нужде литургии: вместо изобразительных, глаголем сице:"},
  {"id": "cu-sve-0281", "section": "service", "who": "priest", "text": "Христо́с воскре́се: трижды."},
  {"id": "cu-sve-0282", "section": "service", "who": "priest", "text": "Воскресе́ние Христо́во:"},
  {"id": "cu-sve-0283", "section": "service", "who": "rubric", "text": "единожды. Посем:"},
  {"id": "cu-sve-0284", "section": "service", "who": "priest", "text": "Предвари́вшия у́тро: Сла́ва: кондак:"},
  {"id": "cu-sve-0285", "section": "service", "who": "priest", "text": "А́ще и во гроб: И ны́не: Единоро́дный Сы́не:"},
  {"id": "cu-sve-0286", "section": "service", "who": "rubric", "text": "Посем блаженна от канона, песнь 3-я и 6-я. Иерей:"},
  {"id": "cu-sve-0287", "section": "service", "who": "priest", "text": "Прему́дрость."},
  {"id": "cu-sve-0288", "section": "service", "who": "rubric", "text": "Чтец надписание Апостола, и самое чтение. Посем иерей Евангелие. Таже,"},
  {"id": "cu-sve-0289", "section": "service", "who": "priest", "text": "Помяни́ нас Го́споди: Лик Небе́сный: И посем:"},
  {"id": "cu-sve-0290", "section": "service", "who": "priest", "text": "Ве́рую во Еди́наго Бо́га: Осла́би, оста́ви: И по"},
  {"id": "cu-sve-0291", "section": "service", "who": "priest", "text": "О́тче наш: кондак:"},
  {"id": "cu-sve-0292", "section": "service", "who": "priest", "text": "А́ще и во гроб: Сла́ва и ны́не: Богородичен:"},
  {"id": "cu-sve-0293", "section": "service", "who": "priest", "text": "Вы́шняго освяще́нное: Го́споди поми́луй, 40. Таже"},
  {"id": "cu-sve-0294", "section": "service", "who": "priest", "text": "Еди́н свят, еди́н Госпо́дь Иису́с Христо́с, во сла́ву Бо́га Отца́. Ами́нь."},
  {"id": "cu-sve-0295", "section": "service", "who": "rubric", "text": "И посем вместо, Буди имя Господне:"},
  {"id": "cu-sve-0296", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0297", "section": "service", "who": "rubric", "text": "трижды. Таже, псалом 33:"},
  {"id": "cu-sve-0298", "section": "service", "who": "priest", "text": "Благословлю́ Го́спода на вся́кое вре́мя: конец:"},
  {"id": "cu-sve-0299", "section": "service", "who": "priest", "text": "не лиша́тся вся́каго бла́га."},
  {"id": "cu-sve-0300", "section": "service", "who": "rubric", "text": "И посем отпуст. И исходим в трапезу."},
  {"id": "cu-sve-0301", "section": "service", "who": "reader", "text": "ПОСЛЕДОВАНИЕ ЛИТУРГИИ, БЫВАЕТ ПОРАНУ"},
  {"id": "cu-sve-0302", "section": "service", "who": "rubric", "text": "Наченшу диакону:"},
  {"id": "cu-sve-0303", "section": "service", "who": "deacon", "text": "Благослови́ влады́ко."},
  {"id": "cu-sve-0304", "section": "service", "who": "rubric", "text": "Настоятелю же возгласившу:"},
  {"id": "cu-sve-0305", "section": "service", "who": "deacon", "text": "Благослове́но Ца́рство Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в. И мы:"},
  {"id": "cu-sve-0306", "section": "service", "who": "deacon", "text": "Ами́нь."},
  {"id": "cu-sve-0307", "section": "service", "who": "deacon", "text": "Настоятель поет с прочими служители во святом олтаре:"},
  {"id": "cu-sve-0308", "section": "service", "who": "deacon", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в, / и су́щим во гробе́х живо́т дарова́в. Трижды."},
  {"id": "cu-sve-0309", "section": "service", "who": "deacon", "text": "И лики тойжде, трижды."},
  {"id": "cu-sve-0310", "section": "service", "who": "choir", "text": "Настоятель глаголет припевы: Первый стих:"},
  {"id": "cu-sve-0311", "section": "service", "who": "choir", "text": "Да воскре́снет Бог, и расточа́тся врази́ Его́, / и да бежа́т от Лица́ Его́ ненави́дящии Его́."},
  {"id": "cu-sve-0312", "section": "service", "who": "choir", "text": "И на кийждо стих мы поем тропарь весь по единожды: Тропарь:"},
  {"id": "cu-sve-0313", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Вторый стих:"},
  {"id": "cu-sve-0314", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sve-0315", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды. Третий стих:"},
  {"id": "cu-sve-0316", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от Лица́ Бо́жия, / а пра́ведницы да возвеселя́тся. Тропарь:"},
  {"id": "cu-sve-0317", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sve-0318", "section": "service", "who": "rubric", "text": "Четвертый стих:"},
  {"id": "cu-sve-0319", "section": "service", "who": "choir", "text": "Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Тропарь:"},
  {"id": "cu-sve-0320", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sve-0321", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху. Тропарь:"},
  {"id": "cu-sve-0322", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sve-0323", "section": "service", "who": "choir", "text": "И ны́не и при́сно и во ве́ки веко́в. Ами́нь. Тропарь:"},
  {"id": "cu-sve-0324", "section": "service", "who": "choir", "text": "Христо́с воскре́се: единожды."},
  {"id": "cu-sve-0325", "section": "service", "who": "rubric", "text": "Таже настоятель поет вышшим гласом:"},
  {"id": "cu-sve-0326", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в. Мы же:"},
  {"id": "cu-sve-0327", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0328", "section": "service", "who": "choir", "text": "Посем глаголет диакон ектению великую. По ектении же и по возгласе:"},
  {"id": "cu-sve-0329", "section": "service", "who": "choir", "text": "Антифон первый, псалом 65, глас 2. Стих 1:"},
  {"id": "cu-sve-0330", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви / вся земля́. Припев:"},
  {"id": "cu-sve-0331", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-sve-0332", "section": "service", "who": "rubric", "text": "И другий лик тойжде стих:"},
  {"id": "cu-sve-0333", "section": "service", "who": "choir", "text": "Воскли́кните Го́сподеви вся земля́, / по́йте же и́мени Его́, дади́те сла́ву хвале́ Его́. Припев:"},
  {"id": "cu-sve-0334", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 2:"},
  {"id": "cu-sve-0335", "section": "service", "who": "choir", "text": "Рцы́те Бо́гу: коль стра́шна дела́ Твоя́, / во мно́жестве си́лы Твоея́ со́лжут Тебе́ врази́ Твои́. Припев:"},
  {"id": "cu-sve-0336", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас. Стих 3:"},
  {"id": "cu-sve-0337", "section": "service", "who": "choir", "text": "Вся земля́ да покло́нится Тебе́, / и пое́т Тебе́, да пое́т же и́мени Твоему́ Вы́шний. Припев:"},
  {"id": "cu-sve-0338", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-sve-0339", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-sve-0340", "section": "service", "who": "rubric", "text": "Купно оба лика вышшим гласом:"},
  {"id": "cu-sve-0341", "section": "service", "who": "choir", "text": "Моли́твами Богоро́дицы, / Спа́се спаси́ нас."},
  {"id": "cu-sve-0342", "section": "service", "who": "choir", "text": "Таже, ектениа малая."},
  {"id": "cu-sve-0343", "section": "service", "who": "choir", "text": "Антифон вторый, псалом 66, глас тойже. Стих 1:"},
  {"id": "cu-sve-0344", "section": "service", "who": "choir", "text": "Бо́же уще́дри ны / и благослови́ ны. Припев:"},
  {"id": "cu-sve-0345", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-sve-0346", "section": "service", "who": "rubric", "text": "Другая страна, тойже стих:"},
  {"id": "cu-sve-0347", "section": "service", "who": "choir", "text": "Бо́же, уще́дри ны и благослови́ ны, / просвети лице Твое́ на ны и поми́луй ны. Припев:"},
  {"id": "cu-sve-0348", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 2:"},
  {"id": "cu-sve-0349", "section": "service", "who": "choir", "text": "Да позна́ем на земли́ путь Твой, / во всех язы́цех спасе́ние Твое́. Припев:"},
  {"id": "cu-sve-0350", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды. Стих 3:"},
  {"id": "cu-sve-0351", "section": "service", "who": "choir", "text": "Да испове́дятся Тебе́ лю́дие, Бо́же, / да испове́дятся Тебе́ лю́дие вси. Припев:"},
  {"id": "cu-sve-0352", "section": "service", "who": "choir", "text": "Спаси́ ны, Сы́не Бо́жий, / воскресы́й из ме́ртвых, пою́щия Ти: / Аллилу́иа. Единожды."},
  {"id": "cu-sve-0353", "section": "service", "who": "choir", "text": "Сла́ва Отцу́ и Сы́ну и Свято́му Ду́ху, / и ны́не и при́сно и во ве́ки веко́в. Ами́нь."},
  {"id": "cu-sve-0354", "section": "service", "who": "rubric", "text": "Вкупе два лика:"},
  {"id": "cu-sve-0355", "section": "service", "who": "choir", "text": "Единоро́дный Сы́не и Сло́ве Бо́жий, Безсме́ртен Сый / и изво́ливый спасе́ния на́шего ра́ди / воплоти́тися от Святы́я Богоро́дицы и Присноде́вы Мари́и, / непрело́жно вочелове́чивыйся, / распны́йся же, Христе́ Бо́же, сме́ртию смерть попра́вый, / Еди́н Сый Святы́я Тро́ицы, / спрославля́емый Отцу́ и Свято́му Ду́ху, спаси́ нас."},
  {"id": "cu-sve-0356", "section": "service", "who": "choir", "text": "Таже, ектениа."},
  {"id": "cu-sve-0357", "section": "service", "who": "choir", "text": "Антифон 3-й, псалом 67, глас 5. Стих 1:"},
  {"id": "cu-sve-0358", "section": "service", "who": "choir", "text": "Да воскре́снет Бог / и расточа́тся врази́ Его́."},
  {"id": "cu-sve-0359", "section": "service", "who": "choir", "text": "Тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0360", "section": "service", "who": "rubric", "text": "Другая страна, той же стих:"},
  {"id": "cu-sve-0361", "section": "service", "who": "choir", "text": "Да воскре́снет Бог и расточа́тся врази́ Его́, / и да бежа́т от лица́ Его́ ненави́дящии Его́. Тропарь:"},
  {"id": "cu-sve-0362", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 2:"},
  {"id": "cu-sve-0363", "section": "service", "who": "choir", "text": "Я́ко исчеза́ет дым, да исче́знут, / я́ко та́ет воск от лица́ огня́. Тропарь:"},
  {"id": "cu-sve-0364", "section": "service", "who": "choir", "text": "Христо́с воскре́се: Стих 3:"},
  {"id": "cu-sve-0365", "section": "service", "who": "choir", "text": "Та́ко да поги́бнут гре́шницы от лица́ Бо́жия, / а пра́ведницы да возвеселя́тся, да возра́дуются пред Бо́гом. Тропарь:"},
  {"id": "cu-sve-0366", "section": "service", "who": "choir", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0367", "section": "service", "who": "rubric", "text": "И бывает вход. И возглашает диакон, аще есть, аще же ни, иерей:"},
  {"id": "cu-sve-0368", "section": "service", "who": "deacon", "text": "Прему́дрость, про́сти."},
  {"id": "cu-sve-0369", "section": "service", "who": "deacon", "text": "Мы же входное: В це́рквах благослови́те Бо́га, Го́спода от исто́чник Изра́илевых."},
  {"id": "cu-sve-0370", "section": "service", "who": "deacon", "text": "И поем тропарь, глас 5: Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в / и су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0371", "section": "service", "who": "deacon", "text": "Ипакои, глас 4: Предвари́вшия у́тро, я́же о Мари́и, / и обре́тшия ка́мень отвале́н от гро́ба, / слы́шаху от А́нгела: во све́те присносу́щнем Су́щаго / с ме́ртвыми что и́щете, я́ко челове́ка? / Ви́дите гро́бныя пелены́, тецы́те и ми́ру пропове́дите, / я́ко воста́ Госпо́дь, умертви́вый смерть, / я́ко есть Сын Бо́га, спаса́ющаго род челове́ческий."},
  {"id": "cu-sve-0372", "section": "service", "who": "deacon", "text": "Слава, и ныне: кондак, глас 8: А́ще и во гроб снизше́л еси́, Безсме́ртне, / но а́дову разруши́л еси́ си́лу, / и воскре́сл еси́, я́ко Победи́тель, Христе́ Бо́же, / жена́м мироно́сицам веща́вый: ра́дуйтеся! / И Твои́м апо́столом мир да́руяй, / па́дшим подая́й воскресе́ние."},
  {"id": "cu-sve-0373", "section": "service", "who": "deacon", "text": "Вместо же Трисвятаго: Ели́цы во Христа́ крести́стеся, / во Христа́ облеко́стеся: / аллилу́иа."},
  {"id": "cu-sve-0374", "section": "service", "who": "rubric", "text": "Подобает ведати, яко сие начало Литургии, и антифоны, и"},
  {"id": "cu-sve-0375", "section": "service", "who": "deacon", "text": "Ели́цы во Христа́ крести́стеся:"},
  {"id": "cu-sve-0376", "section": "service", "who": "rubric", "text": "поем во всю седмицу Светлую, даже до Недели новыя, такожде и причастный."},
  {"id": "cu-sve-0377", "section": "service", "who": "deacon", "text": "Прокимен, глас 8: Сей день, его́же сотвори́ Госпо́дь, / возра́дуемся и возвесели́мся в онь. Стих:"},
  {"id": "cu-sve-0378", "section": "service", "who": "deacon", "text": "Испове́дайтеся Го́сподеви, я́ко благ, я́ко в век ми́лость Его́."},
  {"id": "cu-sve-0379", "section": "service", "who": "deacon", "text": "Деяния святых Апостол, зачало 1."},
  {"id": "cu-sve-0380", "section": "service", "who": "deacon", "text": "Пе́рвое у́бо сло́во сотвори́х о всех, о Фео́филе, я́же нача́т Иису́с твори́ти же и учи́ти. Да́же до дне, во́ньже, запове́дав Апо́столом Ду́хом Святы́м, и́хже избра́, вознесе́ся. Пред ни́миже и поста́ви Себе́ жи́ва по страда́нии Свое́м, во мно́зех [и́стинных] зна́мениих, де́ньми четы́редесятьми явля́яся им, и глаго́ля я́же о Ца́рствии Бо́жии: С ни́миже и яды́й, повеле́ им от Иерусали́ма не отлуча́тися, но жда́ти обетова́ния О́тча, е́же слы́шасте от Мене́: я́ко Иоанн у́бо крести́л есть водо́ю, вы же и́мате крести́тися Ду́хом Святы́м, не по мно́зех сих днех. Они́ же у́бо соше́дшеся, вопроша́ху Его́, глаго́люще: Го́споди, а́ще в ле́то сие́ устроя́еши ца́рствие Изра́илево? Рече́ же к ним: несть ва́ше разуме́ти времена́ и ле́та, я́же Оте́ц положи́ во Свое́й вла́сти: Но прии́мете си́лу, наше́дшу Свято́му Ду́ху на вы, и бу́дете Ми свиде́тели во Иерусали́ме же и во всей Иуде́и и Самари́и, и да́же до после́дних земли́."},
  {"id": "cu-sve-0381", "section": "service", "who": "deacon", "text": "Аллилуия, глас 4 Стих:"},
  {"id": "cu-sve-0382", "section": "service", "who": "deacon", "text": "Ты воскре́с, уще́дриши Сио́на. Стих:"},
  {"id": "cu-sve-0383", "section": "service", "who": "deacon", "text": "Госпо́дь с небесе́ на зе́млю призре́."},
  {"id": "cu-sve-0384", "section": "service", "who": "deacon", "text": "Евангелие от Иоанна, зачало 1."},
  {"id": "cu-sve-0385", "section": "service", "who": "deacon", "text": "В нача́ле бе Сло́во, и Сло́во бе к Бо́гу, и Бог бе Сло́во. Сей бе искони́ к Бо́гу. Вся Тем бы́ша, и без Него́ ничто́же бысть, е́же бысть. В Том живо́т бе, и живо́т бе свет челове́ком. И свет во тьме све́тится, и тьма его́ не объят. Бысть челове́к по́слан от Бо́га, и́мя ему́ Иоа́нн. Сей прии́де во свиде́тельство, да свиде́тельствует о Све́те, да вси ве́ру и́мут Ему́. Не бе той свет, но да свиде́тельствует о Све́те. Бе Свет и́стинный, И́же просвеща́ет вся́каго челове́ка гряду́щаго в мир. В ми́ре бе, и мир Тем бысть, и мир Его́ не позна́. Во своя́ прии́де, и свои́ Его́ не прия́ша. Ели́цы же прия́ша Его́, даде́ им о́бласть ча́дом Бо́жиим бы́ти, ве́рующим во и́мя Его́. И́же не от кро́ве, ни от по́хоти плотски́я, ни от по́хоти му́жеския, но от Бо́га роди́шася. И Сло́во плоть бысть, и всели́ся в ны, и ви́дехом сла́ву Его́, сла́ву я́ко Единоро́днаго от Отца́, испо́лнь благода́ти и и́стины. Иоа́нн свиде́тельствует о Нем и воззва́, глаго́ля: Сей бе, Его́же рех, И́же по мне Гряды́й, пре́до мно́ю бысть, я́ко пе́рвее мене́ бе. И от исполне́ния Его́ мы вси прия́хом, и благода́ть воз благода́ть: Я́ко зако́н Моисе́ом дан бысть, благода́ть же и и́стина Иису́с Христо́м бысть."},
  {"id": "cu-sve-0386", "section": "service", "who": "rubric", "text": "Времене же приспевшу чтения святаго Евангелиа, начальный диакон, хотяй Евангелие чести, глаголет:"},
  {"id": "cu-sve-0387", "section": "service", "who": "deacon", "text": "Благослови́ влады́ко благовести́теля:"},
  {"id": "cu-sve-0388", "section": "service", "who": "rubric", "text": "Таже настоятель глаголет:"},
  {"id": "cu-sve-0389", "section": "service", "who": "deacon", "text": "Бог моли́твами свята́го сла́внаго:"},
  {"id": "cu-sve-0390", "section": "service", "who": "rubric", "text": "и прочая, якоже указася в литургиарии. И исходит диакон, и на обычном месте прямо царских врат, на восток лицем станет, настоятелю прежде возгласившу пред престолом:"},
  {"id": "cu-sve-0391", "section": "service", "who": "deacon", "text": "Прему́дрость про́сти услы́шим свята́го Ева́нгелиа."},
  {"id": "cu-sve-0392", "section": "service", "who": "rubric", "text": "Тожде и вси иереи, елицы суть служащии, по сих же и диакони глаголют, на различных местех ставше, от святаго престола, и до западных врат церковных, един по единому. Посреди же всех стоит архидиакон, и чтут вси по настоятели, един по единому по статиям, якоже настоятель расположит. И предначинает настоятель:"},
  {"id": "cu-sve-0393", "section": "service", "who": "deacon", "text": "От Иоа́нна свята́го Ева́нгелиа чте́ние."},
  {"id": "cu-sve-0394", "section": "service", "who": "rubric", "text": "Прочии тожде. Настоятель:"},
  {"id": "cu-sve-0395", "section": "service", "who": "deacon", "text": "Во́нмем."},
  {"id": "cu-sve-0396", "section": "service", "who": "rubric", "text": "Прочии тожде. Настоятель стоя пред престолом на восток лицем, чтет:"},
  {"id": "cu-sve-0397", "section": "service", "who": "deacon", "text": "В нача́ле бе Сло́во:"},
  {"id": "cu-sve-0398", "section": "service", "who": "rubric", "text": "и прочая. Прочии тожде. И на всяком возгласе, или статии Евангелиа, ударяют в церкви по единощи в кандию. Параекклисиарх же вне церкве в великое било, и в великий кампан, на последнем же возгласе ударяют во вся кампаны, и в великое било, и бывает по чину Божественная Литургиа Златоустаго."},
  {"id": "cu-sve-0399", "section": "service", "who": "deacon", "text": "Вместо же Достойно: поем:"},
  {"id": "cu-sve-0400", "section": "service", "who": "deacon", "text": "А́нгел вопия́ше Благода́тней: / Чи́стая Де́во, ра́дуйся! / И па́ки реку́: ра́дуйся! / Твой Сын воскре́се / тридне́вен от гро́ба, / и ме́ртвыя воздви́гнувый, / лю́дие, весели́теся."},
  {"id": "cu-sve-0401", "section": "service", "who": "rubric", "text": "Таже ирмос, глас 1:"},
  {"id": "cu-sve-0402", "section": "service", "who": "deacon", "text": "Свети́ся, свети́ся, / но́вый Иерусали́ме, / сла́ва бо Госпо́дня / на тебе́ возсия́. / Лику́й ны́не / и весели́ся, Сио́не. / Ты же, Чи́стая, красу́йся, Богоро́дице, / о воста́нии Рождества́ Твоего́."},
  {"id": "cu-sve-0403", "section": "service", "who": "deacon", "text": "Причастный: Те́ло Христо́во приими́те, / исто́чника безсме́ртнаго вкуси́те. / Аллилу́иа. трижды."},
  {"id": "cu-sve-0404", "section": "service", "who": "rubric", "text": "Егда же настоятель глаголет:"},
  {"id": "cu-sve-0405", "section": "service", "who": "deacon", "text": "Со стра́хом Бо́жиим и ве́рою приступи́те."},
  {"id": "cu-sve-0406", "section": "service", "who": "rubric", "text": "Мы вместо, Благословен грядый во имя Господне: поем:"},
  {"id": "cu-sve-0407", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0408", "section": "service", "who": "rubric", "text": "единожды. Настоятель глаголет:"},
  {"id": "cu-sve-0409", "section": "service", "who": "deacon", "text": "Спаси́ Бо́же лю́ди Твоя́: И мы:"},
  {"id": "cu-sve-0410", "section": "service", "who": "deacon", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0411", "section": "service", "who": "rubric", "text": "единожды. Егда же изглаголет иерей:"},
  {"id": "cu-sve-0412", "section": "service", "who": "priest", "text": "Всегда́ ны́не и при́сно: И мы:"},
  {"id": "cu-sve-0413", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0414", "section": "service", "who": "rubric", "text": "единожды. Посем ектениа. Вместо же, Буди имя Господне: и вместо псалма, Благословлю Господа: поем:"},
  {"id": "cu-sve-0415", "section": "service", "who": "priest", "text": "Христо́с воскре́се:"},
  {"id": "cu-sve-0416", "section": "service", "who": "rubric", "text": "дванадесять, и множае: дондеже анафора от игумена раздастся. Таже настоятель,"},
  {"id": "cu-sve-0417", "section": "service", "who": "priest", "text": "Благослове́ние Госпо́дне на вас:"},
  {"id": "cu-sve-0418", "section": "service", "who": "choir", "text": "Ами́нь."},
  {"id": "cu-sve-0419", "section": "service", "who": "rubric", "text": "Посем настоятель вместо, Слава Тебе Христе Боже: поет:"},
  {"id": "cu-sve-0420", "section": "service", "who": "choir", "text": "Христо́с воскре́се из ме́ртвых, / сме́ртию смерть попра́в."},
  {"id": "cu-sve-0421", "section": "service", "who": "rubric", "text": "И лик:"},
  {"id": "cu-sve-0422", "section": "service", "who": "choir", "text": "И су́щим во гробе́х живо́т дарова́в."},
  {"id": "cu-sve-0423", "section": "service", "who": "rubric", "text": "Посем настоятель глаголет отпуст со Крестом по обычаю, якоже указася на Утрени."},
  {"id": "cu-sve-0424", "section": "service", "who": "choir", "text": "Да будет же вестно и се, яко врат царских олтаря, великих же и от стран малых, по всем церквам во всю Светлую седмицу не затворяем и во время причащения."},
  {"id": "cu-sve-0425", "section": "service", "who": "deacon", "text": "Молитва на благословение артоса во святую Неделю Пасхи."},
  {"id": "cu-sve-0426", "section": "service", "who": "rubric", "text": "Принесен бывает артос, сиесть хлеб на сие приуготовленный, и на нем крест написанный обычно, к иерею в олтарь, по совершении Божественныя Литургии и по заамвонней молитве, рекшу диакону:"},
  {"id": "cu-sve-0427", "section": "service", "who": "deacon", "text": "Го́споду помо́лимся. И клиру:"},
  {"id": "cu-sve-0428", "section": "service", "who": "deacon", "text": "Го́споди, поми́луй."},
  {"id": "cu-sve-0429", "section": "service", "who": "deacon", "text": "Чтет над ним иерей молитву сию: Бо́же всеси́льный и Го́споди Вседержи́телю, и́же рабо́м Твои́м Моисе́ом во исхо́де Изра́илеве от Еги́пта, и в освобожде́нии люде́й Твои́х от го́рькия рабо́ты фарао́новы, а́гнца закла́ти повеле́л еси́, прообразу́я на кресте́ закла́ннаго во́лею нас де́ля А́гнца, взе́млющаго всего́ мiра грехи́, возлю́бленнаго Сы́на Твоего́, Го́спода на́шего Иису́са Христа́. Ты и ны́не, смире́нно мо́лим Тя, при́зри на хлеб сей, и благослови́, и освяти́ его́. И́бо и мы, раби́ Твои́, в честь и сла́ву, и в воспомина́ние сла́внаго воскресе́ния того́жде Сы́на Твоего́ Го́спода на́шего Иису́са Христа́, И́мже от ве́чныя рабо́ты вра́жия и от а́довых нереши́мых уз разреше́ние, свобо́ду и преведе́ние улучи́хом, пред Твои́м вели́чеством ны́не во всесве́тлый сей, пресла́вный и спаси́тельный день Па́схи, сей прино́сим: нас же сего́ принося́щих, и того́ лобза́ющих, и от него́ вкуша́ющих, Твоему́ небе́сному благослове́нию прича́стники бы́ти сотвори́ и вся́кую боле́знь и неду́г от нас Твое́ю си́лою отжени́, здра́вие всем подава́я. Ты бо еси́ исто́чник благослове́ния и цельба́м пода́тель, и Тебе́ сла́ву возсыла́ем Безнача́льному Отцу́, со Единоро́дным Твои́м Сы́ном, и Пресвяты́м и Благи́м и Животворя́щим Твои́м Ду́хом, ны́не и при́сно и во ве́ки веко́в."},
  {"id": "cu-sve-0430", "section": "service", "who": "choir", "text": "Ами́нь."},
  {"id": "cu-sve-0431", "section": "service", "who": "rubric", "text": "Абие же кропит артос священною водою, глаголя:"},
  {"id": "cu-sve-0432", "section": "service", "who": "choir", "text": "Благословля́ется и освяща́ется а́ртос сей, окропле́нием воды́ сея́ свяще́нныя, во и́мя Отца́ и Сы́на и Свята́го Ду́ха. Ами́нь. Трижды."},
  {"id": "cu-sve-0433", "section": "service", "who": "choir", "text": "И посем исходит, и полагает его на аналогии, людие же приемлюще антидор, лобзают артос. Ведомо же буди и се, яко мяс православнии христиане к церкви не приносят, но в дом ко иерею."},
  {"id": "cu-sve-0434", "section": "service", "who": "rubric", "text": "Молитва во еже благословити брашна мяс, во святую и великую Неделю Пасхи. Творит иерей: Благослове́н Бог наш: Христо́с воскре́се: трижды. Таже: Го́споду помо́лимся. Го́споди поми́луй. При́зри Го́споди Иису́се Христе́ Бо́же наш, на бра́шна мяс, и освяти́ я́, я́коже освяти́л еси́ овна́, его́же Тебе́ приведе́ ве́рный Авраа́м, и а́гнца, его́же Тебе́ А́вель во всепло́дие принесе́: подо́бне и тельца́ упита́ннаго, его́же жре́ти повеле́л еси́ сы́нови Твоему́ заблу́ждшему, и па́ки к Тебе́ возвра́щшемуся: да я́коже той сподо́бися Твоея́ бла́гости наслади́тися, си́це и освяще́нных от Тебе́, и благослове́нных наслади́мся в пи́щу всех нас. Ты бо еси́ и́стинная пи́ща, и пода́тель благи́х, и Тебе́ сла́ву возсыла́ем со Безнача́льным Твои́м Отце́м, и Пресвяты́м, и Благи́м, и Животворя́щим Твои́м Ду́хом, ны́не и при́сно и во ве́ки веко́в. Ами́нь. Молитва во еже благословити сыр и яица. Яица же и сыр принесенныя поставляются в притворе, в церковь же отнюд не подобает вносити. Священник же изшед глаголет: Го́споду помо́лимся. Влады́ко Го́споди Бо́же наш, зижди́телю и соде́телю всех, благослови́ млеко́ огусте́вшее, с ни́мже и я́ица, и нас соблюди́ во бла́гости Твое́й, я́ко да причаща́ющеся их, Твои́х незави́стно пода́тельных даро́в испо́лнимся, и неизглаго́ланныя Твоея́ бла́гости: я́ко Твоя́ держа́ва, и Твое́ есть Ца́рство, и си́ла, и сла́ва, Отца́ и Сы́на и Свята́го Ду́ха, ны́не и при́сно и во ве́ки веко́в. Ами́нь. Вестно же буди: яко сицевый, мяс и набелу, принос, несть пасха, ниже агнец, якоже нецыи глаголют, и приемлют, и ему со всяким говением якоже некоей святыни причащаются, но простое приношение. Не аки бо сие в жертву Богу приноситися имать, но токмо да начинающим по посте мясо и сыр ясти, от иереа предложенными молитвами в снедь благословено будет. Пасха бо Сам Христос есть и Агнец вземляй грехи мира, на олтари в безкровной Жертве, в пречистых Тайнах, честнаго Тела, и животворящия Крове Своея, от иереа Богу и Отцу приносимый, и Тому достойно причащающиися истинную ядят Пасху. И сего ради оныя приносы, яко не суть пасха, во олтарь или в церковь не достоит вносити, но вне церкве, или в притворе, молитвою благословити, по третиему правилу святых апостол глаголющих: Аще кто епископ, или пресвитер, кроме вчинения Господня о жертве, иная некая ко олтарю принесет, мед или млеко, или вместо вина сикеру, сиесть оловину, или медовину, или птицы, или кая животная, или сочива, разве гроздия в лете, и елеа на свещники, и фимиама во время Литургии, да извержется. И по шестому собору, иже в Трулле, в правиле 99-м, глаголющу: И сему во Арменстей стране бывати уведехом, яко нецыи внутрь во святых олтарех уды мяс варяще, части приносят священником, жидовски разделяюще. Темже Церковь непорочну храняще, узаконихом, яко не подобает ниединому же священнику различных мяс частей от приносящих приимати, но теми довольни да будут, яже приносящему возмнятся. Сицевому приношению бываему вне церкви: аще же кто сего не сотворит, да отлучится. Подобает ведати, яко аще случится брату коему отыти ко Господу в сию святую седмицу Пасхи: и о сем зри всего последования сих дней о усопших в Требнике."},
];

